import { useState, useEffect, useRef } from 'react';
import clsx from 'clsx';
import './AcidCountUp.css';

export interface AcidCountUpProps {
    end: number;
    start?: number;
    duration?: number;
    prefix?: string;
    suffix?: string;
    decimals?: number;
    className?: string;
    label?: string;
}

export const AcidCountUp = ({
    end,
    start = 0,
    duration = 2000,
    prefix = '',
    suffix = '',
    decimals = 0,
    className,
    label
}: AcidCountUpProps) => {
    const [count, setCount] = useState(start);
    const countRef = useRef(start);
    const startTimeRef = useRef<number | null>(null);

    useEffect(() => {
        let animationFrameId: number;

        const updateCount = (timestamp: number) => {
            if (!startTimeRef.current) startTimeRef.current = timestamp;
            const progress = Math.min((timestamp - startTimeRef.current) / duration, 1);

            // Ease out quad
            const easeProgress = progress * (2 - progress);
            const currentCount = start + easeProgress * (end - start);

            setCount(currentCount);
            countRef.current = currentCount;

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(updateCount);
            }
        };

        animationFrameId = requestAnimationFrame(updateCount);
        return () => cancelAnimationFrame(animationFrameId);
    }, [end, start, duration]);

    const formattedCount = count.toFixed(decimals);

    return (
        <div className={clsx('ac-count-up', className)}>
            <div className="ac-count-up-main">
                {prefix && <span className="ac-count-up-prefix">{prefix}</span>}
                <span className="ac-count-up-value">{formattedCount}</span>
                {suffix && <span className="ac-count-up-suffix">{suffix}</span>}
            </div>
            {label && <div className="ac-count-up-label">{label}</div>}
            <div className="ac-count-up-scanline" />
        </div>
    );
};

.ac-count-up {
    position: relative;
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid var(--ac-border-muted);
    padding: 1rem 1.5rem;
    border-radius: 4px;
    overflow: hidden;
    min-width: 120px;
}

.ac-count-up-main {
    display: flex;
    align-items: baseline;
    gap: 2px;
    font-family: var(--font-mono);
    color: var(--ac-brand);
    font-weight: 700;
}

.ac-count-up-prefix,
.ac-count-up-suffix {
    font-size: 0.8rem;
    opacity: 0.7;
    color: var(--ac-text-secondary);
}

.ac-count-up-value {
    font-size: 1.5rem;
    letter-spacing: -0.05em;
    text-shadow: 0 0 10px rgba(var(--ac-brand-rgb), 0.3);
}

.ac-count-up-label {
    margin-top: 4px;
    font-size: 0.6rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--ac-text-muted);
    font-weight: 600;
}

.ac-count-up-scanline {
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom,
            transparent 50%,
            rgba(255, 255, 255, 0.02) 50%);
    background-size: 100% 4px;
    pointer-events: none;
    opacity: 0.5;
}
